class Solution:
    def deleteString(self, s: str) -> int:
        n = len(s)
        MOD, B = (1 << 61) - 1, 131
        h = [0]*(n+1); p = [1]*(n+1)
        for i, c in enumerate(s):
            h[i+1] = (h[i]*B + ord(c)) % MOD
            p[i+1] = p[i]*B % MOD
        def get(l, r):
            return (h[r] - h[l]*p[r-l]) % MOD
        dp = [0]*(n+1)
        for i in range(n-1, -1, -1):
            dp[i] = 1
            for j in range(1, (n-i)//2 + 1):
                if get(i, i+j) == get(i+j, i+2*j):
                    dp[i] = max(dp[i], 1 + dp[i+j])
        return dp[0]

