class Solution {
public:
    int deleteString(string s) {
        int n = s.size();
        const unsigned long long MOD = (1ULL << 61) - 1, B = 131;
        vector<unsigned long long> h(n+1, 0), p(n+1, 1);
        for (int i = 0; i < n; i++) {
            h[i+1] = (h[i]*B + s[i]) % MOD;
            p[i+1] = p[i]*B % MOD;
        }
        auto get = [&](int l, int r) { return (h[r] + MOD*MOD - h[l]*p[r-l] % MOD) % MOD; };
        vector<int> dp(n+1, 0);
        for (int i = n-1; i >= 0; i--) {
            dp[i] = 1;
            for (int j = 1; j <= (n-i)/2; j++)
                if (get(i, i+j) == get(i+j, i+2*j)) dp[i] = max(dp[i], 1 + dp[i+j]);
        }
        return dp[0];
    }
};

