class Solution {
    public int deleteString(String s) {
        int n = s.length();
        long MOD = (1L << 61) - 1, B = 131;
        long[] h = new long[n+1], p = new long[n+1];
        for (int i = 0; i < n; i++) {
            h[i+1] = (int)(((h[i]*B + s.charAt(i)) % MOD));
            p[i+1] = p[i]*B % MOD;
        }
        var dp = new int[n+1];
        for (int i = n-1; i >= 0; i--) {
            dp[i] = 1;
            for (int j = 1; j <= (n-i)/2; j++) {
                long a = ((h[i+j] - h[i]*p[j]) % MOD + MOD) % MOD;
                long b = ((h[i+2*j] - h[i+j]*p[j]) % MOD + MOD) % MOD;
                if (a == b) dp[i] = Math.max(dp[i], 1 + dp[i+j]);
            }
        }
        return dp[0];
    }
}

